const __aivicBundle_8_calculateProjectDelayRiskScore = (() => {
  async function calculateProjectDelayRiskScore(
    input: {
      issueFrequency: number;
      impactScore: number;
      averageResolutionDays: number;
      currentUnresolvedDays: number;
    }
  ): Promise<ProjectDelayRiskScoreResult> {
    const {
      issueFrequency,
      impactScore,
      averageResolutionDays,
      currentUnresolvedDays,
    } = input;
  
    // 過去の解決期間データを取得して基準値を確定
    const historicalData = await retrieveIssueDataByCondition({
      startDate: new Date(Date.now() - 90 * 24 * 60 * 60 * 1000), // 過去90日
      endDate: new Date(),
      statusList: ["resolved"],
    });
  
    // 過去データから平均解決期間を計算（基準値確定）
    let baselineResolutionDays = averageResolutionDays;
    if (historicalData.issues.length > 0) {
      const totalDays = historicalData.issues.reduce((sum, issue) => {
        const extractedDate = new Date(issue.extractedDate);
        const daysSinceExtraction = Math.ceil(
          (new Date().getTime() - extractedDate.getTime()) / (1000 * 60 * 60 * 24)
        );
        return sum + daysSinceExtraction;
      }, 0);
      baselineResolutionDays = totalDays / historicalData.issues.length;
    }
  
    // リスクスコア計算：頻出度と影響度の加重平均 + 解決期間の遅延係数
    const frequencyWeight = 0.4;
    const impactWeight = 0.4;
    const resolutionDelayWeight = 0.2;
  
    // 頻出度スコア（0～100に正規化）
    const frequencyScore = Math.min(issueFrequency * 10, 100);
  
    // 影響度スコア（既に0～100の範囲）
    const impactScoreNormalized = Math.min(Math.max(impactScore, 0), 100);
  
    // 解決期間遅延係数（現在の未解決日数が基準を超えた場合のペナルティ）
    const delayRatio = Math.max(
      currentUnresolvedDays / Math.max(baselineResolutionDays, 1),
      0
    );
    const resolutionDelayScore = Math.min(delayRatio * 100, 100);
  
    // 加重平均でリスクスコアを算出
    const riskScore = Math.round(
      frequencyScore * frequencyWeight +
        impactScoreNormalized * impactWeight +
        resolutionDelayScore * resolutionDelayWeight
    );
  
    // リスク水準を判定
    let riskLevel: "HIGH" | "MEDIUM" | "LOW" | "high" | "medium" | "low";
    if (riskScore >= 70) {
      riskLevel = "high";
    } else if (riskScore >= 40) {
      riskLevel = "medium";
    } else {
      riskLevel = "low";
    }
  
    // 遅延日数推定：未解決日数が基準を超えた分を推定遅延とする
    const delayDaysEstimate = Math.max(
      currentUnresolvedDays - baselineResolutionDays,
      0
    );
  
    return {
      riskScore,
      riskLevel,
      delayDaysEstimate: Math.round(delayDaysEstimate),
    };
  }
  return { calculateProjectDelayRiskScore };
})();
